    await window.advisorJson('/api/g2/advisor/client-portfolios/link',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({organizationId:String(client.organizationId),clientId,portfolioId,role:'PRIMARY'})});
    if(refresh)await loadDomain();
